    "printedExplanation": "계절별 기온은 태양의 남중 고도와 관련이 있습니다. 태양의 남중 고도가 높을수록 좁은 면적을 비추기 때문에 단위 면적의 지표면에 도달하는 태양 에너지의 양이 많아 기온이 높습니다. 겨울보다 여름의 기온이 높은 것은 겨울보다 여름에 태양의 남중 고도가 높기 때문입니다.",
