    "printedExplanation": "지구의의 자전축이 기울어진 것과 기울어지지 않은 것을 비교하면 가설이 옳은지 확인할 수 있습니다. 이때 자전축의 기울기 이외에 조건은 모두 같게 해 줍니다.",
    "printedRubric": null,
