    "prompt": "위 실험 과정을 순서대로 기호를 나열하세요.",
    "choices": null,
    "sourceContextBlocks": [
     {
      "type": "text",
      "text": "다음은 지구의의 자전축을 수직으로 하여 전등 주위를 공전시키며 태양의 남중 고도 변화를 알아보는 실험 과정을 순서 없이 나타낸 것입니다. 물음에 답하세요."
     },
     {
      "type": "figure",
      "src": "assets/bank/c22-s62-u01/legacy-s62-season-s4-upright-globe.png",
      "alt": "전등 주위의 지구의 네 개가 뒤 (가), 왼쪽 (나), 앞 (다), 오른쪽 (라)에 있어요. 자전축은 수직이고 노란 화살표가 네 위치를 차례로 이어요."
     },
     {
      "type": "list",
      "items": [
       "ㄱ. 태양 고도 측정기를 붙인 지구의의 자전축을 수직으로 맞추고, 전등으로부터 30 cm 떨어진 거리에 둡니다.",
       "ㄴ. 지구의를 시계 반대 방향으로 공전시켜 각 위치에서 태양의 남중 고도를 측정합니다.",
       "ㄷ. 전등의 높이를 태양 고도 측정기의 높이와 비슷하게 조절하고 전등을 켠 다음, 태양의 남중 고도를 측정합니다."
      ]
     }
    ],
